"""Independent finite naturality/ownership and partial-square controls. AuthorityEffect: None."""
NAT=r'''
fn c2()->DeclaredFiniteCategory{let mut c=DeclaredFiniteCategory::new("C2");for a in 0..2{c.add_morphism(&a.to_string(),"*","*");}c.set_identity("*","0");for a in 0..2{for b in 0..2{c.set_composition(&a.to_string(),&b.to_string(),&((a+b)%2).to_string());}}c}
fn endo(name:&str,generator:usize)->DeclaredFiniteFunctor{let mut f=DeclaredFiniteFunctor::new(name,"C2","C2");f.map_object("*","*");f.map_morphism("0","0");f.map_morphism("1",&generator.to_string());f}
fn nat(name:&str,f:&str,g:&str,component:usize)->DeclaredFiniteNatTrans{let mut n=DeclaredFiniteNatTrans::new(name,f,g);n.set_component("*",&component.to_string());n}
fn has_nat(report:&ValidationReport,unit:NatTransValidation)->bool{report.typed_violations.iter().any(|v|v.unit==ValidationUnit::NatTrans(unit))}
#[test]fn all_c2_endofunctor_component_choices_match_group_naturality_oracle(){
 let c=c2();for fg in 0..2{for gg in 0..2{for eta in 0..2{let f=endo("F",fg);let g=endo("G",gg);let n=nat("eta","F","G",eta);let report=validate_natural_transformation_between(&n,&c,&c,&f,&g);assert_eq!(report.all_passed(),fg==gg);assert_eq!(report.target_name,"eta");assert_eq!(report.results.len(),7);assert_eq!(ValidatedFiniteNatTrans::try_new(n,&c,&c,&f,&g).is_ok(),fg==gg);}}}
 let f=endo("F",0);let n=nat("e","F","F",1);assert_eq!(validate_natural_transformation_between(&n,&c,&c,&f,&f).results.len(),6);
 let empty=DeclaredFiniteCategory::new("empty");let f=DeclaredFiniteFunctor::new("F","empty","empty");let g=DeclaredFiniteFunctor::new("G","empty","empty");let n=DeclaredFiniteNatTrans::new("empty eta","F","G");assert!(ValidatedFiniteNatTrans::try_new(n,&empty,&empty,&f,&g).is_ok());
}
#[test]fn full_admission_has_all_typed_refusals_and_rejects_bad_endpoint_functors(){
 let c=c2();let f=endo("F",0);let g=endo("G",0);let good=nat("eta","F","G",0);let check=|n:&DeclaredFiniteNatTrans,u|{let report=validate_natural_transformation_between(n,&c,&c,&f,&g);assert!(!report.all_passed());assert!(has_nat(&report,u));assert!(report.typed_violations.iter().all(|v|v.severity==ValidationSeverity::Error));assert!(report.typed_violations.iter().filter(|v|matches!(v.unit,ValidationUnit::NatTrans(_))).all(|v|v.location==ValidationLocation::Global&&!v.message.is_empty()));};
 let mut n=good.clone();n.name=" \t".into();check(&n,NatTransValidation::Name);for source in [true,false]{let mut n=good.clone();if source{n.source_functor="bad".into();}else{n.target_functor="bad".into();}check(&n,NatTransValidation::FunctorBinding);}
 let mut n=good.clone();n.components.clear();check(&n,NatTransValidation::ComponentDomain);check(&n,NatTransValidation::ComponentBoundary);let mut n=good.clone();n.set_component("extra","0");check(&n,NatTransValidation::ComponentDomain);let mut n=good.clone();n.set_component("*","unknown");check(&n,NatTransValidation::ComponentBoundary);
 let mut bad=c.clone();bad.compositions.clear();assert!(ValidatedFiniteNatTrans::try_new(good.clone(),&bad,&c,&f,&g).is_err());assert!(ValidatedFiniteNatTrans::try_new(good.clone(),&c,&bad,&f,&g).is_err());for source in [true,false]{let mut bad=f.clone();bad.morphism_map.clear();if source{assert!(ValidatedFiniteNatTrans::try_new(good.clone(),&c,&c,&bad,&g).is_err());}else{bad.name=g.name.clone();assert!(ValidatedFiniteNatTrans::try_new(good.clone(),&c,&c,&f,&bad).is_err());}}
 let f=endo("same",0);let mut g=f.clone();g.morphism_map.clear();let n=nat("eta","same","same",0);assert_eq!(validate_natural_transformation_between(&n,&c,&c,&f,&g).results.len(),7);assert!(ValidatedFiniteNatTrans::try_new(n.clone(),&c,&c,&f,&g).is_err());let mut g=f.clone();g.source_category="wrong".into();assert!(ValidatedFiniteNatTrans::try_new(n,&c,&c,&f,&g).is_err());
 let w=crate::finite_category_builder::DeclaredFiniteCategoryBuilder::walking_arrow("W","A","B","f").build();let f=crate::functor_composition::identity_functor(&w,"F");let g=crate::functor_composition::identity_functor(&w,"G");let mut n=DeclaredFiniteNatTrans::new("n","F","G");n.set_component("A","f");n.set_component("B","id_B");assert!(has_nat(&validate_natural_transformation_between(&n,&w,&w,&f,&g),NatTransValidation::ComponentBoundary));
 let f=endo("F",0);let g=endo("G",1);let n=nat("eta","F","G",0);assert!(has_nat(&validate_natural_transformation_between(&n,&c,&c,&f,&g),NatTransValidation::NaturalitySquare));
}
#[test]fn owned_certificate_snapshots_and_raw_component_maps_remain_distinct(){
 let mut c=c2();let mut f=endo("F",0);let mut g=endo("G",0);let mut n=DeclaredFiniteNatTrans::new("eta","F","G");assert!(n.components.is_empty());assert_eq!(n.component("*"),None);n.set_component("*","wrong");n.set_component("*","1");assert_eq!((n.name.as_str(),n.source_functor.as_str(),n.target_functor.as_str()),("eta","F","G"));assert_eq!(n.component("*"),Some("1"));assert_eq!(n.components.len(),1);let saved_n=n.clone();let saved_c=c.clone();let saved_f=f.clone();let saved_g=g.clone();let cert=ValidatedFiniteNatTrans::try_new(n,&c,&c,&f,&g).unwrap();c.compositions.clear();f.object_map.clear();g.morphism_map.clear();assert_eq!(cert.declared(),&saved_n);assert_eq!(cert.source_category(),&saved_c);assert_eq!(cert.target_category(),&saved_c);assert_eq!(cert.source_functor(),&saved_f);assert_eq!(cert.target_functor(),&saved_g);assert_eq!(cert,cert.clone());assert!(format!("{:?}",cert).contains("eta"));let mut raw=cert.declared().clone();raw.components.clear();assert!(ValidatedFiniteNatTrans::try_new(raw,&saved_c,&saved_c,&saved_f,&saved_g).is_err());assert_eq!(cert.declared(),&saved_n);
 // Endpoints/functors must differ observably to detect swapped snapshot fields.
 let mut target=saved_c.clone();target.name="D".into();let mut f=saved_f;f.target_category="D".into();let mut g=saved_g;g.target_category="D".into();let cert=ValidatedFiniteNatTrans::try_new(saved_n,&saved_c,&target,&f,&g).unwrap();assert_eq!(cert.source_category(),&saved_c);assert_eq!(cert.target_category(),&target);assert_eq!(cert.source_functor(),&f);assert_eq!(cert.target_functor(),&g);
}
#[test]fn partial_square_presence_truth_table_preserves_first_missing_and_defined_equality(){
 let mut source=DeclaredFiniteCategory::new("raw");source.add_morphism("f","A","B");for present in 0..64{for wrong in [false,true]{let mut n=DeclaredFiniteNatTrans::new("n","F","G");if present&1!=0{n.set_component("A","ea");}if present&2!=0{n.set_component("B","eb");}let mut f=BTreeMap::new();let mut g=BTreeMap::new();if present&4!=0{f.insert("f".into(),"Ff".into());}if present&8!=0{g.insert("f".into(),"Gf".into());}let mut table=BTreeMap::new();if present&16!=0{table.insert(("Ff".into(),"eb".into()),"L".into());}if present&32!=0{table.insert(("ea".into(),"Gf".into()),if wrong{"R"}else{"L"}.into());}
 let expected=if present&1==0{vec!["Missing component at A"]}else if present&2==0{vec!["Missing component at B"]}else if present&4==0{vec!["Missing F(f)"]}else if present&8==0{vec!["Missing G(f)"]}else if present&16==0{vec!["Missing eta_B after F(f)"]}else if present&32==0{vec!["Missing G(f) after eta_A"]}else if wrong{vec!["Naturality fails at f: left L, right R"]}else{vec![]};assert_eq!(check_naturality_square(&n,&source,&f,&g,&table),expected,"present={present},wrong={wrong}");let empty=DeclaredFiniteCategory::new("empty");assert!(check_naturality_square(&n,&empty,&f,&g,&table).is_empty());}}
 let mut n=DeclaredFiniteNatTrans::new("n","F","G");n.set_component("A","e");let source=crate::finite_category_builder::DeclaredFiniteCategoryBuilder::walking_arrow("W","A","B","f").build();let errors=check_naturality_square(&n,&source,&BTreeMap::new(),&BTreeMap::new(),&BTreeMap::new());assert_eq!(errors,vec!["Missing component at B","Missing F(id_A)","Missing component at B"]);
}
#[test]fn component_boundaries_cover_all_presence_and_independent_endpoint_cases(){
 let mut source=DeclaredFiniteCategory::new("S");source.add_object("A");for present in 0..16{for wrong in 0..4{let mut n=DeclaredFiniteNatTrans::new("n","F","G");if present&1!=0{n.set_component("A","eta");}let mut f=DeclaredFiniteFunctor::new("F","S","D");let mut g=DeclaredFiniteFunctor::new("G","S","D");if present&2!=0{f.map_object("A","X");}if present&4!=0{g.map_object("A","Y");}let mut target=DeclaredFiniteCategory::new("D");let actual_s=if wrong&1!=0{"badS"}else{"X"};let actual_t=if wrong&2!=0{"badT"}else{"Y"};if present&8!=0{target.add_morphism("eta",actual_s,actual_t);}
 let expected=if present&1==0{vec!["Natural transformation: η_A is not defined".to_string()]}else if present&2==0{vec!["Natural transformation: F(A) is not defined".into()]}else if present&4==0{vec!["Natural transformation: G(A) is not defined".into()]}else if present&8==0{vec!["Natural transformation: component η_A = eta is not a target morphism".into()]}else if wrong!=0{vec![format!("Natural transformation: η_A = eta has boundary {actual_s} -> {actual_t}, expected X -> Y")]}else{vec![]};assert_eq!(check_component_boundaries(&n,&source,&target,&f,&g),expected);}}
}
'''

def challenge(subject):
    return '\n#[cfg(test)] mod independent_naturality_tests { use super::*;\n'+NAT+'\n}\n'
